import { query } from "@anthropic-ai/claude-agent-sdk";

const session = query({
  prompt: "Reply with the single word: pong",
  options: {
    model: "claude-haiku-5-5", // the cheapest model; enough for one word
    effort: "low",
    tools: [], // no built-in tools: the model can only answer
    settingSources: [], // ignore every settings file on this laptop
  },
});

for await (const msg of session) {
  if (msg.type === "system" && msg.subtype === "init") {
    console.log("init", msg.model, msg.claude_code_version, msg.permissionMode);
  } else if (msg.type === "assistant") {
    console.log("assistant", JSON.stringify(msg.message.content));
  } else if (msg.type === "result") {
    console.log("result", msg.subtype, msg.num_turns, "turns, cost", msg.total_cost_usd);
    console.log("models used", Object.keys(msg.modelUsage));
    console.log("session_id", msg.session_id);
  }
}

const options: Options = {
  // ...
  pathToClaudeCodeExecutable: "/usr/local/bin/claude", // the pinned binary the nightly smoke test passed (G3-14)
};

import {
  createSdkMcpServer, type Options, type SessionStore,
} from "@anthropic-ai/claude-agent-sdk/core";
